import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class Main {
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD) @interface PostConstruct {}
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD) @interface PreDestroy {}
    interface InitializingBean { void afterPropertiesSet(); }
    interface DisposableBean { void destroy(); }
    interface Bpp { Object apply(Object b, String n); }

    static class Bean implements InitializingBean, DisposableBean {
        String dep;
        StringBuilder seq = new StringBuilder();
        @PostConstruct void pc() { seq.append("postConstruct->"); }
        public void afterPropertiesSet() { seq.append("initializingBean->"); }
        void initMethod() { seq.append("initMethod->"); }
        @PreDestroy void pd() { seq.append("preDestroy->"); }
        public void destroy() { seq.append("disposableBean->"); }
        String run() { return "run:" + dep; }
    }

    public static void main(String[] args) throws Exception {
        Bean b = new Bean();
        System.out.println("1.instantiate");
        b.dep = "injected";
        System.out.println("2.populate dep=" + b.dep);
        Bpp before = (bean, name) -> { System.out.println("3.bpp-before " + name); return bean; };
        b = (Bean) before.apply(b, "bean");
        for (Method m : Bean.class.getDeclaredMethods()) if (m.isAnnotationPresent(PostConstruct.class)) m.invoke(b);
        b.afterPropertiesSet();
        Bean.class.getDeclaredMethod("initMethod").invoke(b);
        Bpp after = (bean, name) -> { System.out.println("4.bpp-after " + name); return bean; };
        b = (Bean) after.apply(b, "bean");
        System.out.println("5.init done seq=" + b.seq);
        System.out.println("6.use " + b.run());
        for (Method m : Bean.class.getDeclaredMethods()) if (m.isAnnotationPresent(PreDestroy.class)) m.invoke(b);
        b.destroy();
        System.out.println("7.destroy seq=" + b.seq);
    }
}
